// Des: Commands ingest and social: load Facebook and Zalo records
// Flo: ingest [dir] counts (dry-run) or saves records as pages (--live) > social runs the engines from soci_engi_list first (--live only) then ingests > cars calls the same ingest before it parses
// I/O: Ctx (config, db) > one line or JSON, exit code; scra never logs in to Facebook or Zalo, the engines fb and za do
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const inge = @import("ru-soci-inge.zig"); const spaw = @import("ru-soci-spaw.zig"); const pexp = @import("ut-path-expa.zig");
const CF = .{ .sdir = "social-in" };
const Outp = struct { mode: []const u8, srcd: []const u8, engi: u32, fail: u32, file: u32, line: u32, news: u32, chan: u32, same: u32, bads: u32 };
pub fn srcdOfzz(ctx2: *const ctx3.Ctxz) ![]const u8 { if (ctx2.args.urlz.len > 0 and std.mem.eql(u8, ctx2.args.cmdz, "ingest")) return ctx2.args.urlz; if (ctx2.conf.soci_dirz.len > 0) return pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.soci_dirz) catch return error.BadConfig; return std.fs.path.join(ctx2.allo, &.{ ctx2.dirz, CF.sdir }); }
pub fn cronIngt(ctx2: *const ctx3.Ctxz, dbzx: ?*@import("st-stor-sqli.zig").Dbzz, dryz: bool) !inge.Ires { if (!ctx2.conf.soci_enab) return .{}; return inge.ingeRunz(dbzx, ctx2.iozz, ctx2.dirz, try srcdOfzz(ctx2), ctx2.conf, ctx2.init.gpa, dryz); }
fn outpMake(ctx2: *const ctx3.Ctxz, dryz: bool, srcd: []const u8, sres: spaw.Sres, ires: inge.Ires) !u8 { const outp: Outp = .{ .mode = if (dryz) "dry-run" else "live", .srcd = srcd, .engi = sres.engi, .fail = sres.fail, .file = ires.file, .line = ires.line, .news = ires.news, .chan = ires.chan, .same = ires.same, .bads = ires.bads }; const plai = try std.fmt.allocPrint(ctx2.allo, "{s} {s} | engines {d} run, {d} failed | {s} | files {d}, records {d} ({d} new, {d} changed, {d} same), {d} bad{s}", .{ ctx2.args.cmdz, outp.mode, outp.engi, outp.fail, srcd, outp.file, outp.line, outp.news, outp.chan, outp.same, outp.bads, if (dryz) " | add --live to run" else "" }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outp, plai)); return if (sres.fail > 0) 1 else 0; }
pub fn runzIngt(ctx2: *const ctx3.Ctxz) !u8 { const dryz = !ctx2.args.live; const srcd = try srcdOfzz(ctx2); if (dryz) { const ires = try inge.ingeRunz(null, ctx2.iozz, ctx2.dirz, srcd, ctx2.conf, ctx2.init.gpa, true); return outpMake(ctx2, true, srcd, .{}, ires); } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const ires = try inge.ingeRunz(&dbzz, ctx2.iozz, ctx2.dirz, srcd, ctx2.conf, ctx2.init.gpa, false); return outpMake(ctx2, false, srcd, .{}, ires); }
pub fn runzSoci(ctx2: *const ctx3.Ctxz) !u8 { const dryz = !ctx2.args.live; const srcd = try srcdOfzz(ctx2); if (dryz) { const ires = try inge.ingeRunz(null, ctx2.iozz, ctx2.dirz, srcd, ctx2.conf, ctx2.init.gpa, true); return outpMake(ctx2, true, srcd, .{ .engi = @intCast(ctx2.conf.soci_engi_list.len) }, ires); } const sres = try spaw.spawRunz(ctx2.allo, ctx2.iozz, ctx2.conf.soci_engi_list, ctx2.conf.soci_time_seco); var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const ires = try inge.ingeRunz(&dbzz, ctx2.iozz, ctx2.dirz, srcd, ctx2.conf, ctx2.init.gpa, false); return outpMake(ctx2, false, srcd, sres, ires); }
